package de.nevergate.verkehr;
import java.util.*;
import java.util.function.Consumer;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.entity.vehicle.Boat;
import net.minecraft.world.item.ItemStack;
import net.minecraftforge.common.MinecraftForge;
import net.minecraftforge.gametest.GameTestHolder;
import static de.nevergate.verkehr.OperationsBlock.Kind.*;
@GameTestHolder(value=NgTraffic.ID,namespace=NgTraffic.ID)
public final class OperationsGameTests {
    static BlockPos origin(GameTestHelper h){return h.absolutePos(new BlockPos(2,2,2));}
    static OperationsEntity put(GameTestHelper h,BlockPos p,OperationsBlock.Kind k){h.getLevel().removeBlock(p,false);h.getLevel().setBlock(p,NgTraffic.OPERATIONS.get(k).get().defaultBlockState(),3);return (OperationsEntity)h.getLevel().getBlockEntity(p);}
    static Boat car(GameTestHelper h,BlockPos pos){var e=new Boat(h.getLevel(),pos.getX()+.5,pos.getY()+.2,pos.getZ()+2.5);e.setNoGravity(true);e.noPhysics=true;h.getLevel().addFreshEntity(e);return e;}
    static Consumer<VehicleServiceEvent> provider(Boat car,UUID owner,boolean electric,int fuel,int cap,int dirt,int[] calls,boolean fail){return e->{if(e.vehicle!=car)return;if(e.operation==VehicleServiceEvent.Operation.READ)e.describe(new VehicleServiceEvent.View(car.getUUID(),owner,"NG-123","car","petrol",fuel,cap,dirt,electric,0,electric?50000:0));else{calls[0]++;if(fail)throw new IllegalStateException("simulated durable operation failure");e.complete(e.operation==VehicleServiceEvent.Operation.WASH?1:Math.min(500,e.requested),"receipt-"+e.transaction);}};}
    @GameTest(template="ng_verkehr:empty",timeoutTicks=20)
    public static void timeWindowsSupportMidnightAndExactBoundaries(GameTestHelper h){h.assertTrue(OperationsEntity.inWindow(16000,22,6)&&!OperationsEntity.inWindow(0,22,6)&&OperationsEntity.inWindow(2000,8,17)&&!OperationsEntity.inWindow(11000,8,17),"Window boundaries wrong");h.succeed();}
    @GameTest(template="ng_verkehr:empty",timeoutTicks=20)
    public static void forgedCardCannotOpenBollard(GameTestHelper h){var pos=origin(h);var r=put(h,pos,CARD_READER);var b=put(h,pos.east(),ROAD_BOLLARD);var a=ServiceGameTests.player(h,pos,true);var p=ServiceGameTests.player(h,pos,false);r.connect(b,a);var card=new ItemStack(NgTraffic.ACCESS_CARD.get());card.getOrCreateTag().putUUID("Card",UUID.randomUUID());card.getOrCreateTag().putUUID("Reader",r.identity());p.getInventory().add(card);h.assertTrue(!r.action(p,0),"Forged card accepted");h.succeed();}
    @GameTest(template="ng_verkehr:empty",timeoutTicks=20)
    public static void issuedCardWorksAndRevocationSurvivesReload(GameTestHelper h){var pos=origin(h);var r=put(h,pos,CARD_READER);var b=put(h,pos.east(),ROAD_BOLLARD);var a=ServiceGameTests.player(h,pos,true);r.connect(b,a);h.assertTrue(r.issueCard(a)&&r.action(a,0),"Issued card failed");r.action(a,21);r.load(r.saveWithoutMetadata());h.assertTrue(!r.action(a,0),"Revoked card resurrected");h.succeed();}
    @GameTest(template="ng_verkehr:empty",timeoutTicks=20)
    public static void copiedCardIsBoundToHolder(GameTestHelper h){var pos=origin(h);var r=put(h,pos,CARD_READER);var b=put(h,pos.east(),ROAD_BOLLARD);var a=ServiceGameTests.player(h,pos,true);var p=ServiceGameTests.player(h,pos,false);r.connect(b,a);r.issueCard(a);p.getInventory().add(a.getInventory().getItem(0).copy());h.assertTrue(!r.action(p,0),"Foreign holder used copied card");h.succeed();}
    @GameTest(template="ng_verkehr:empty",timeoutTicks=20)
    public static void replacementGateDoesNotInheritPermission(GameTestHelper h){var pos=origin(h);var r=put(h,pos,CARD_READER);var b=put(h,pos.east(),ROAD_BOLLARD);var a=ServiceGameTests.player(h,pos,true);r.connect(b,a);r.issueCard(a);put(h,pos.east(),ROAD_BOLLARD);h.assertTrue(r.linked(ROAD_BOLLARD)==null&&!r.action(a,0),"Replacement gate accepted stale identity");h.succeed();}
    @GameTest(template="ng_verkehr:empty",timeoutTicks=20)
    public static void survivalAndForeignCreativeCannotEditOwnedDevice(GameTestHelper h){var pos=origin(h);var n=put(h,pos,TUNNEL_CALL);var owner=ServiceGameTests.player(h,pos,true);n.setOwner(owner.getUUID());var p=ServiceGameTests.player(h,pos,false);var stranger=ServiceGameTests.player(h,pos,true);h.assertTrue(!n.action(p,10)&&!n.action(stranger,10)&&n.action(owner,10),"Ownership/admin checks wrong");h.succeed();}
    @GameTest(template="ng_verkehr:empty",timeoutTicks=35)
    public static void bollardRetainsSafePositionUnderObstruction(GameTestHelper h){var pos=origin(h);var b=put(h,pos,ROAD_BOLLARD);h.getLevel().setBlock(pos,b.getBlockState().setValue(OperationsBlock.STATUS,1),3);var car=car(h,pos);car.setPos(pos.getX()+.5,pos.getY()+.1,pos.getZ()+.5);h.runAfterDelay(8,()->{h.assertTrue(b.open(),"Bollard raised into vehicle");car.discard();});h.runAfterDelay(32,()->{h.assertTrue(!b.open(),"Bollard did not close after obstruction left");h.succeed();});}
    @GameTest(template="ng_verkehr:empty",timeoutTicks=20)
    public static void reloadDoesNotPreserveOpenLease(GameTestHelper h){var pos=origin(h);var r=put(h,pos,CARD_READER);var b=put(h,pos.east(),ROAD_BOLLARD);var a=ServiceGameTests.player(h,pos,true);r.connect(b,a);r.issueCard(a);r.action(a,0);b.load(b.saveWithoutMetadata());h.assertTrue(!b.open(),"Reload preserved open lease");h.succeed();}
    @GameTest(template="ng_verkehr:empty",timeoutTicks=45)
    public static void emergencyPersistsAndEscapeRouteResponds(GameTestHelper h){var pos=origin(h);var c=put(h,pos,TUNNEL_CALL);var s=put(h,pos.east(),ESCAPE_SIGN);var a=ServiceGameTests.player(h,pos,true);var p=ServiceGameTests.player(h,pos,false);s.connect(c,a);h.assertTrue(c.action(p,0),"Public emergency call rejected");c.load(c.saveWithoutMetadata());h.runAfterDelay(8,()->{h.assertTrue(c.alarm()&&s.alarm()&&s.detail().contains("FLUCHTWEG"),"Emergency not retained/propagated");h.assertTrue(!c.action(p,17)&&c.action(a,17),"Emergency acknowledgement not protected");});h.runAfterDelay(20,()->{h.assertTrue(!s.alarm(),"Acknowledged alarm retained");h.succeed();});}
    @GameTest(template="ng_verkehr:empty",timeoutTicks=35)
    public static void operationsDeskReportsMissingLinkedDevices(GameTestHelper h){var pos=origin(h);var d=put(h,pos,OPERATIONS_DESK);var c=put(h,pos.east(),TUNNEL_CALL);d.connect(c,ServiceGameTests.player(h,pos,true));h.runAfterDelay(8,()->h.getLevel().removeBlock(pos.east(),false));h.runAfterDelay(24,()->{h.assertTrue(d.alarm()&&d.faults()==1,"Desk ignored missing device");h.succeed();});}
    @GameTest(template="ng_verkehr:empty",timeoutTicks=20)
    public static void busRouteAndSchedulePersist(GameTestHelper h){var pos=origin(h);var n=put(h,pos,BUS_ROUTE);n.route("42","NeverGate Hauptbahnhof");n.schedule(22,6);n.load(n.saveWithoutMetadata());h.assertTrue(n.line().equals("42")&&n.destination().equals("NeverGate Hauptbahnhof")&&n.startHour()==22&&n.endHour()==6,"Route persistence failed");h.succeed();}
    @GameTest(template="ng_verkehr:empty",timeoutTicks=35)
    public static void busArrivalRequiresCorrectLinkedRoute(GameTestHelper h){var pos=origin(h);var route=put(h,pos,BUS_ROUTE);var sensor=put(h,pos.east(),BUS_SENSOR);var display=put(h,pos.east(2),BUS_DISPLAY);var a=ServiceGameTests.player(h,pos,true);sensor.connect(route,a);display.connect(route,a);display.connect(sensor,a);var car=car(h,pos);car.addTag("ng_bus");h.runAfterDelay(16,()->{h.assertTrue(sensor.open()&&display.online()&&display.detail().contains("JETZT"),"Bus arrival missing");car.discard();h.succeed();});}
    @GameTest(template="ng_verkehr:empty",timeoutTicks=25)
    public static void busDisplayRejectsDifferentSensorRoute(GameTestHelper h){var pos=origin(h);var route=put(h,pos,BUS_ROUTE);var other=put(h,pos.east(),BUS_ROUTE);var sensor=put(h,pos.east(2),BUS_SENSOR);var display=put(h,pos.east(3),BUS_DISPLAY);var a=ServiceGameTests.player(h,pos,true);sensor.connect(other,a);display.connect(route,a);display.connect(sensor,a);h.runAfterDelay(16,()->{h.assertTrue(!display.online(),"Wrong route presented live arrival");h.succeed();});}
    @GameTest(template="ng_verkehr:empty",timeoutTicks=35)
    public static void workExitDetectsAndClearsVehicleWarning(GameTestHelper h){var pos=origin(h);var n=put(h,pos,WORK_EXIT);var car=car(h,pos);h.runAfterDelay(8,()->{h.assertTrue(n.alarm(),"Vehicle exit warning missing");car.discard();});h.runAfterDelay(20,()->{h.assertTrue(!n.alarm(),"Vehicle exit warning stuck");h.succeed();});}
    @GameTest(template="ng_verkehr:empty",timeoutTicks=35)
    public static void manualVisibilityWarningAndRedstonePersist(GameTestHelper h){var pos=origin(h);var n=put(h,pos,VISIBILITY_CONTROL);var a=ServiceGameTests.player(h,pos,true);n.action(a,16);n.load(n.saveWithoutMetadata());h.runAfterDelay(8,()->{h.assertTrue(n.alarm()&&n.getBlockState().getValue(OperationsBlock.STATUS)==2,"Visibility warning lost");h.succeed();});}
    @GameTest(template="ng_verkehr:empty",timeoutTicks=25)
    public static void deliveryZoneWithoutGateNeverReportsOpen(GameTestHelper h){var pos=origin(h);var n=put(h,pos,DELIVERY_ZONE);n.schedule(0,0);h.runAfterDelay(8,()->{h.assertTrue(!n.open()&&!n.online(),"Unlinked delivery access reported open");h.succeed();});}
    @GameTest(template="ng_verkehr:empty",timeoutTicks=20)
    public static void missingVehicleAdapterCannotStartService(GameTestHelper h){var pos=origin(h);var n=put(h,pos,FUEL_PUMP);var p=ServiceGameTests.player(h,pos,true);n.action(p,23);var car=car(h,pos);h.assertTrue(!n.action(p,0)&&n.state()==0,"Missing provider started service");car.discard();h.succeed();}
    @GameTest(template="ng_verkehr:empty",timeoutTicks=20)
    public static void paidServiceIsBlockedWithoutEconomicProtocol(GameTestHelper h){var pos=origin(h);var n=put(h,pos,FUEL_PUMP);var p=ServiceGameTests.player(h,pos,true);var car=car(h,pos);int[] calls={0};var provider=provider(car,p.getUUID(),false,0,50000,90,calls,false);MinecraftForge.EVENT_BUS.addListener(provider);try{h.assertTrue(!n.action(p,0)&&calls[0]==0,"Paid service executed without payment");}finally{MinecraftForge.EVENT_BUS.unregister(provider);car.discard();}h.succeed();}
    @GameTest(template="ng_verkehr:empty",timeoutTicks=20)
    public static void starterBatteryIsNotTractionBattery(GameTestHelper h){var pos=origin(h);var n=put(h,pos,CHARGER);var p=ServiceGameTests.player(h,pos,true);n.action(p,23);var car=car(h,pos);int[] calls={0};var provider=provider(car,p.getUUID(),false,0,50000,90,calls,false);MinecraftForge.EVENT_BUS.addListener(provider);try{h.assertTrue(!n.action(p,0)&&calls[0]==0,"Non-electric vehicle charged");}finally{MinecraftForge.EVENT_BUS.unregister(provider);car.discard();}h.succeed();}
    @GameTest(template="ng_verkehr:empty",timeoutTicks=20)
    public static void actualFuelAmountConfirmedAndImmediateDuplicateRejected(GameTestHelper h){var pos=origin(h);var n=put(h,pos,FUEL_PUMP);var p=ServiceGameTests.player(h,pos,true);n.action(p,23);var car=car(h,pos);int[] calls={0};var provider=provider(car,p.getUUID(),false,0,50000,90,calls,false);MinecraftForge.EVENT_BUS.addListener(provider);try{h.assertTrue(n.action(p,0)&&n.state()==2&&n.detail().contains("500 ml"),"Actual delivered quantity missing");h.assertTrue(!n.action(p,0)&&calls[0]==1,"Immediate duplicate executed twice");}finally{MinecraftForge.EVENT_BUS.unregister(provider);car.discard();}h.succeed();}
    @GameTest(template="ng_verkehr:empty",timeoutTicks=20)
    public static void fullTankAndForeignPlayerRejected(GameTestHelper h){var pos=origin(h);var n=put(h,pos,FUEL_PUMP);var p=ServiceGameTests.player(h,pos,true);n.action(p,23);var car=car(h,pos);int[] calls={0};var provider=provider(car,p.getUUID(),false,50000,50000,90,calls,false);MinecraftForge.EVENT_BUS.addListener(provider);try{h.assertTrue(!n.action(p,0),"Full tank accepted");}finally{MinecraftForge.EVENT_BUS.unregister(provider);}var other=provider(car,UUID.randomUUID(),false,0,50000,90,calls,false);MinecraftForge.EVENT_BUS.addListener(other);try{h.assertTrue(!n.action(p,0)&&calls[0]==0,"Foreign vehicle modified");}finally{MinecraftForge.EVENT_BUS.unregister(other);car.discard();}h.succeed();}
    @GameTest(template="ng_verkehr:empty",timeoutTicks=20)
    public static void providerExceptionLocksUncertainTransactionAcrossReload(GameTestHelper h){var pos=origin(h);var n=put(h,pos,FUEL_PUMP);var p=ServiceGameTests.player(h,pos,true);n.action(p,23);var car=car(h,pos);int[] calls={0};var provider=provider(car,p.getUUID(),false,0,50000,90,calls,true);MinecraftForge.EVENT_BUS.addListener(provider);try{n.action(p,0);h.assertTrue(n.state()==3,"Exception not marked uncertain");n.load(n.saveWithoutMetadata());h.assertTrue(n.state()==3&&!n.action(p,0)&&!n.action(p,1)&&calls[0]==1,"Uncertain transaction retried or discarded");}finally{MinecraftForge.EVENT_BUS.unregister(provider);car.discard();}h.succeed();}
    @GameTest(template="ng_verkehr:empty",timeoutTicks=20)
    public static void pendingWashAbortsOnReloadWithoutExecution(GameTestHelper h){var pos=origin(h);var n=put(h,pos,WASH_TUNNEL);var p=ServiceGameTests.player(h,pos,true);n.action(p,23);var car=car(h,pos);int[] calls={0};var provider=provider(car,p.getUUID(),false,0,50000,90,calls,false);MinecraftForge.EVENT_BUS.addListener(provider);try{h.assertTrue(n.action(p,0)&&n.state()==1,"Wash did not start");n.load(n.saveWithoutMetadata());h.assertTrue(n.state()==4&&calls[0]==0,"Wash resumed after reload");}finally{MinecraftForge.EVENT_BUS.unregister(provider);car.discard();}h.succeed();}
    @GameTest(template="ng_verkehr:empty",timeoutTicks=20)
    public static void secretCardRegistryNotSentInUpdatePacket(GameTestHelper h){var pos=origin(h);var n=put(h,pos,CARD_READER);n.issueCard(ServiceGameTests.player(h,pos,true));h.assertTrue(n.saveWithoutMetadata().contains("Cards")&&!n.getUpdateTag().contains("Cards")&&!n.getUpdateTag().contains("Owner"),"Authority registry leaked to client");h.succeed();}
    @GameTest(template="ng_verkehr:empty",timeoutTicks=20)
    public static void invalidAdapterSnapshotAndOverdeliveryRejected(GameTestHelper h){var pos=origin(h);var car=car(h,pos);var p=ServiceGameTests.player(h,pos,true);boolean rejected=false;try{new VehicleServiceEvent.View(car.getUUID(),p.getUUID(),"NG","car","petrol",100,20,0,false,0,0);}catch(IllegalArgumentException e){rejected=true;}h.assertTrue(rejected,"Invalid capacity accepted");var e=new VehicleServiceEvent(car,p,UUID.randomUUID(),VehicleServiceEvent.Operation.FUEL,100);rejected=false;try{e.complete(101,"proof");}catch(IllegalArgumentException ex){rejected=true;}h.assertTrue(rejected&&!e.completed(),"Overdelivery accepted");car.discard();h.succeed();}
    @GameTest(template="ng_verkehr:empty",timeoutTicks=20)
    public static void plateNormalizationAndLimits(GameTestHelper h){var pos=origin(h);var n=put(h,pos,PLATE_READER);h.assertTrue(OperationsEntity.normalizePlate(" ng - 123 ").equals("NG123")&&n.addPlate("ng - 123")&&!n.addPlate("../../x")&&!n.addPlate("x".repeat(40)),"Plate normalization / validation wrong");h.succeed();}
    @GameTest(template="ng_verkehr:empty",timeoutTicks=25)
    public static void chargerParkAndCashierRequireLinkedDevices(GameTestHelper h){var pos=origin(h);var c=put(h,pos,CHARGE_CONTROL);var f=put(h,pos.east(),FUEL_CASHIER);h.runAfterDelay(8,()->{h.assertTrue(!c.online()&&!f.online(),"Empty controller claimed ready");h.succeed();});}
    @GameTest(template="ng_verkehr:empty",timeoutTicks=20)
    public static void allTwentyDevicesHaveMenusAndOwnedLinks(GameTestHelper h){var pos=origin(h);var p=ServiceGameTests.player(h,pos,true);for(var k:OperationsBlock.Kind.values()){var n=put(h,pos,k);var m=new OperationsMenu(1,p.getInventory(),n);h.assertTrue(m.kind==k&&m.stillValid(p),"Device menu missing "+k);}h.assertTrue(OperationsBlock.Kind.values().length==20,"Unexpected scope");h.succeed();}
    @GameTest(template="ng_verkehr:empty",timeoutTicks=35)
    public static void schoolWarningAndAlwaysOpenDeliveryWindow(GameTestHelper h){var pos=origin(h);var n=put(h,pos,SCHOOL_WARNING);n.schedule(0,0);var d=put(h,pos.east(),DELIVERY_ZONE);var b=put(h,pos.east(2),ROAD_BOLLARD);d.schedule(0,0);d.connect(b,ServiceGameTests.player(h,pos,true));h.runAfterDelay(16,()->{h.assertTrue(n.alarm()&&d.open()&&b.open(),"Scheduled warning / delivery gate failed");h.succeed();});}
    @GameTest(template="ng_verkehr:empty",timeoutTicks=20)
    public static void electricAdapterAllowsActualCharge(GameTestHelper h){var pos=origin(h);var n=put(h,pos,CHARGER);var p=ServiceGameTests.player(h,pos,true);n.action(p,23);var car=car(h,pos);int[] calls={0};var provider=provider(car,p.getUUID(),true,0,0,0,calls,false);MinecraftForge.EVENT_BUS.addListener(provider);try{h.assertTrue(n.action(p,0)&&n.state()==2&&n.detail().contains("500 Wh"),"Electric charge not confirmed");}finally{MinecraftForge.EVENT_BUS.unregister(provider);car.discard();}h.succeed();}
    @GameTest(template="ng_verkehr:empty",timeoutTicks=25)
    public static void deskCanWatchExistingTrafficDevices(GameTestHelper h){var pos=origin(h);var d=put(h,pos,OPERATIONS_DESK);var call=ServiceGameTests.put(h,pos.east(),ServiceBlock.Kind.PEDESTRIAN_CALL);h.assertTrue(d.connect(call,ServiceGameTests.player(h,pos,true)),"Existing traffic device not connectable");h.runAfterDelay(12,()->{h.assertTrue(d.faults()==1&&d.alarm(),"Existing device fault not reported");h.succeed();});}

    @GameTest(template="ng_verkehr:empty",timeoutTicks=20)
    public static void journalPreventsRevokedCardResurrectionFromStaleChunk(GameTestHelper h){var pos=origin(h);var r=put(h,pos,CARD_READER);var b=put(h,pos.east(),ROAD_BOLLARD);var a=ServiceGameTests.player(h,pos,true);r.connect(b,a);r.issueCard(a);var stale=r.saveWithoutMetadata();r.action(a,21);r.load(stale);h.assertTrue(!r.action(a,0),"Stale chunk resurrected revoked card");h.succeed();}
    @GameTest(template="ng_verkehr:empty",timeoutTicks=20)
    public static void journalKeepsUncertainOperationWhenChunkHasOldState(GameTestHelper h){var pos=origin(h);var n=put(h,pos,FUEL_PUMP);var p=ServiceGameTests.player(h,pos,true);n.action(p,23);var stale=n.saveWithoutMetadata();var car=car(h,pos);int[] calls={0};var provider=provider(car,p.getUUID(),false,0,50000,90,calls,true);MinecraftForge.EVENT_BUS.addListener(provider);try{n.action(p,0);n.load(stale);h.assertTrue(!n.action(p,0)&&n.state()==3&&calls[0]==1,"Stale chunk retried unknown operation");}finally{MinecraftForge.EVENT_BUS.unregister(provider);car.discard();}h.succeed();}

}
